package com.smarthire.controller;
import com.smarthire.dto.JobRequest; import com.smarthire.entity.Job; import com.smarthire.service.JobService; import jakarta.validation.Valid; import java.security.Principal; import java.util.List; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/jobs") public class JobController { private final JobService jobs; public JobController(JobService jobs){this.jobs=jobs;} @GetMapping public List<Job> list(){return jobs.list();} @GetMapping("/mine") public List<Job> mine(Principal p){return jobs.mine(p.getName());} @GetMapping("/{id}") public Job get(@PathVariable Long id){return jobs.get(id);}@PostMapping public ResponseEntity<Job> create(Principal p,@Valid @RequestBody JobRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(jobs.create(p.getName(),r));} @PutMapping("/{id}") public Job update(Principal p,@PathVariable Long id,@Valid @RequestBody JobRequest r){return jobs.update(p.getName(),id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deactivate(Principal p,@PathVariable Long id){jobs.deactivate(p.getName(),id);}}
